import{_ as n,l as r,o as e,c as s,v as o,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"家庭债务与周期","description":"","frontmatter":{"title":"家庭债务与周期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/household-debt-cycles.md","filePath":"econ/household-debt-cycles.md","lastUpdated":1789023840000}'),h={name:"econ/household-debt-cycles.md"};function E(u,a,m,B,_,f){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="家庭债务与周期" tabindex="-1">家庭债务与周期 <a class="header-anchor" href="#家庭债务与周期" aria-label="Permalink to &quot;家庭债务与周期&quot;">​</a></h1><div class="epigraph"><p>杠杆把房价与收入冲击放大成消费崩溃：高债务地区在去杠杆时 MPC 更高，加总看起来像需求冲击。</p><footer>—— Mian and Sufi, House of Debt；Mian, Rao and Sufi, Household Balance Sheets, Consumption, and the Great Recession, QJE 2013</footer></div><p><a href="/econ/ui-moral-hazard">上一课</a>的保险对象是失业流。大衰退里更刺眼的是<strong>资产负债表</strong>。本课缺口是家庭杠杆如何把资产价格变成加总需求。不重写 Baily 公式，不把 Kiyotaki–Moore 的企业抵押提前当主模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mian–Sufi：2000 年代按揭扩张、房价下跌后，高杠杆邮编的消费与就业掉得更狠。名义债、住房抵押、去杠杆时的高 MPC，使财富冲击不像代表性欧拉里的小财富效应。缺口是把 HANK 的约束从「偶发借贷下限」升级成<strong>周期性的债务积压</strong>，并与识别课的加总 IRF 对话：看起来像偏好冲击的，可能是债务分布。</p><p><span class="marginnote">Mian, Rao and Sufi, <em>QJE</em> 2013。Mian and Sufi, <em>QJE</em> 2009 等。Eggertsson–Krugman 的借款人–储蓄人是后课名义模型；本课先钉经验机制与资产负债表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>截面：用杠杆与房价暴露的地区变异识别消费弹性。宏观模型：异质住房、按揭约束、名义债。冲击：房价、利率、信贷供给。IRF 状态依存：债务/收入高时同一利率脉冲更大——可用 LP 的状态依存，识别仍要外来。与住房作为资产：本栏不估计住房 CAPM。</p>',8)),(e(),l(p,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E6%88%BF%E4%BB%B7%20%2F%20%E4%BF%A1%E8%B4%B7%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20LEV%5B%22%E5%AE%B6%E5%BA%AD%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20CONS%5B%22%E7%BA%A6%E6%9D%9F%E4%B8%8E%20MPC%22%5D%0A%20%20CONS%20--%3E%20DEM%5B%22%E5%9C%B0%E5%8C%BA%E4%B8%8E%E5%8A%A0%E6%80%BB%E9%9C%80%E6%B1%82%22%5D%0A%20%20DEM%20--%3E%20JOB%5B%22%E5%B0%B1%E4%B8%9A%E5%8F%8D%E9%A6%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>银行中介如何放贷，留给 Gertler–Kiyotaki。本课家庭侧：即使银行无损，家庭去杠杆也能制造衰退。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是名义刚性债遇到资产价格下跌：净值蒸发，约束绑住，MPC 升，需求降，劳动收入再降。若债是浮动利率，货币政策的直接现金流通道变强（Auclert）。若债是固定利率长期按揭，通道弱一些，但再融资与房价仍在。分配：债权人的正财富效应通常 MPC 更低，加总净效应为负。</p><p>与 \\(r\\gt g\\)：长期财富份额 vs 周期性杠杆，不是同一课。危机十年里顶层份额与中产住房净值可以反向动。</p><p><span class="marginnote">Justiniano, Primiceri and Tambalotti 把信贷供给与住房写入 DSGE。Guerrieri and Lorenzoni 的信贷紧缩异质模型。本课保持宏观，不写贷款级证券化结构的全部细节——影子银行后课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写宏观审慎 LTV 的最优公式（后课）。不把个人破产法写完。企业债务积压是公司金融与后课企业异质。限价簿上的抵押品定价不是这里的房价指数。</p><p>后课默认：家庭杠杆使需求冲击的截面可预测；加总 IRF 可能是债务分布的投影。本单元最后一课：企业侧异质投资。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>家庭债务把资产价格冲击变成高 MPC 的消费崩溃。</li><li>债权人与债务人的 MPC 不对称，加总为负。</li><li>与 UI 的保险对象不同：这是存量杠杆。</li><li>出处：Mian, Rao and Sufi, <em>QJE</em> 2013；Mian and Sufi, <em>House of Debt</em>。</li></ul>',10))])}const C=n(h,[["render",E]]);export{P as __pageData,C as default};
